bool valid(long long k, long long a, long long b, long long c) {
    while (a > 0 || b > 0 || c > 0) {
        long long da = a % k;
        long long db = b % k;
        long long dc = c % k;

        if ((da + db) % k != dc) return false;

        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;

        long long d = a + b - c;

        if (d < 0) {
            cout << 0 << '\n';
        } else if (d == 0) {
            cout << -1 << '\n';
        } else {
            int answer = 0;
            for (long long i = 1; i * i <= d; ++i) {
                if (d % i != 0) continue;

                long long j = d / i;
                if (i >= 2 && valid(i, a, b, c)) ++answer;
                if (j != i && j >= 2 && valid(j, a, b, c)) ++answer;
